// Get the text output from the previous Gemini node
// Note: 'text' matches the key we saw in your log: {"text": "```json..."}
const aiResponse = $input.first().json.message.content;

// 1. Remove the Markdown code blocks (```json and ```)
let cleanJson = aiResponse.replace(/```json/g, "").replace(/```/g, "").trim();

// 2. Parse the string into a real JSON object
try {
  const parsedData = JSON.parse(cleanJson);

  // 3. Return the clean object
  return { json: parsedData };
} catch (error) {
  // Fallback if AI returned bad JSON
  return { json: { error: "Failed to parse JSON", raw: aiResponse } };
}
